export type VerifiedStatus = "appointment_verified" | "inquiry_verified" | "service_record_verified" | "invoice_verified" | "fleet_confirmed" | "admin_verified" | "pending_approval" | "approved_without_visit" | "rejected";

/** suggestions only; applying them is a normal update */
export type VinDecodeResult = {
  decode_status: "decoded" | "partial" | "failed";
  suggested: {
    license_plate?: string;
    nickname?: string;
    brand_node_id?: string;
    model_node_id?: string;
    series_node_id?: string;
    /** ≤ current year + 2 */
    year?: number;
    engine_type_node_id?: string;
    fuel_type_node_id?: string;
    transmission?: "manual" | "automatic" | "cvt" | "dct" | "other";
    drivetrain?: "fwd" | "rwd" | "awd" | "4wd";
    body_style?: "sedan" | "hatchback" | "wagon" | "coupe" | "convertible" | "suv" | "pickup" | "van" | "minivan" | "other";
    color?: string;
    mileage_km?: number;
    ownership_start_date?: string;
    primary_photo_media_id?: string;
    notes?: string;
    data_sharing?: "appointments" | "private";
  };
  decoder_source: string;
};

// --- Server-defined schemas (OpenAPI components; backend DI-50)

/** Snapshot of the inputs a badge rule (rule_version) evaluated (54 §6; modules/trust/domain/scoring.ts): counts, ratings and thresholds, no personal data. */
export type BadgeEvaluation = Record<string, unknown>;

/** Display card of a Discover feed item, by kind: nearby_provider / recommended_for_vehicle — the public organization card (plus brand_node_id); showcase — the public portfolio item with its organization card; followed_update — the public post; qna — {title, status, answer_count, created_at}; maintenance_tip — {title, reminder_type, status, priority} of the caller own reminder. Public data only. */
export type FeedCard = Record<string, unknown>;

/** Structured payload of an AI insight, validated per insight type before storage (SEC-AI-5; modules/ai-mcp/domain/payloads.ts). Insight types without a schema have structured_payload null. */
export type InsightPayload = InsightPayload_appointment_slot_suggestion | InsightPayload_capability_suggestion | InsightPayload_fitment_suggestion | InsightPayload_fleet_suggestion | InsightPayload_fraud_flag | InsightPayload_inventory_gap | InsightPayload_inventory_normalization | InsightPayload_maintenance_suggestion | InsightPayload_pre_visit_summary | InsightPayload_redaction_suggestion | InsightPayload_review_response_draft | InsightPayload_review_theme | InsightPayload_service_history_summary | InsightPayload_showcase_caption | InsightPayload_skill_heatmap | InsightPayload_triage_summary | InsightPayload_vehicle_field_suggestion | InsightPayload_vehicle_summary;

/** Public values behind a match reason (54 §5), by reason_type: capability_evidence {level, jobs, offered, covered, system_node_id, task_node_id, brand_node_id, matching_items, fitment_confidence}; rating_evidence {avg_rating (decimal string), reviews}; location {distance_km (decimal string) | null}; availability {next_available_at, in_stock_items, …}; urgency_fit {urgency_level, fast}; user_preference {favorite, preferred_partner}; trust_signal {verified, badge}. Clients render the summary text; unknown keys are ignored. */
export type MatchReasonValues = Record<string, string | number | boolean | null>;

/** Properties of a registered client analytics event (modules/analytics/domain/events.ts); unknown names, properties or values refuse the event. Values come from closed vocabularies: no free text, ids of people or coordinates. */
export type RegisteredEventProperties = RegisteredEventProperties_app_opened | RegisteredEventProperties_map_directions_tapped | RegisteredEventProperties_map_opened | RegisteredEventProperties_map_pin_selected | RegisteredEventProperties_map_vehicle_filter_toggled | RegisteredEventProperties_onboarding_step_completed | RegisteredEventProperties_profile_viewed | RegisteredEventProperties_search_chip_edited | RegisteredEventProperties_search_result_opened | RegisteredEventProperties_search_safety_banner_shown | RegisteredEventProperties_search_started;

/** Proposed (or edited) change of an AI suggestion, validated per target type; accepting applies it through the owning module. Other target types carry null. */
export type SuggestionPayload = SuggestionPayload_inventory_item | SuggestionPayload_maintenance_reminder | SuggestionPayload_organization | SuggestionPayload_vehicle;

/** Plain fields of the moderated record for moderators (ModerationTargets of the owning module), never contact data or secrets; {type, id, available: false} when the record is gone. */
export type TargetSnapshot = {
  type?: string;
  id?: string;
  available?: boolean;
};

/** Plain values for the notification template (template_key) that the client renders from the UI dictionary; never markup or personal data beyond the recipient own. */
export type TemplateParams = Record<string, string | number | boolean>;

/** WebAuthn Level 3 AuthenticationResponseJSON (PublicKeyCredential.toJSON()) for the ceremony of auth.webauthn_options. */
export type WebAuthnAssertion = {
  id: string;
  rawId: string;
  type: "public-key";
  response: {
    clientDataJSON: string;
    authenticatorData: string;
    signature: string;
    userHandle?: string;
  };
  authenticatorAttachment?: "platform" | "cross-platform";
  clientExtensionResults: Record<string, unknown>;
};

/** WebAuthn Level 3 RegistrationResponseJSON for the options of me.webauthn_register_options (attestation none, user verification required). Device-bound credentials give aal3, synced passkeys aal2 (GD-31). */
export type WebAuthnAttestation = {
  id: string;
  rawId: string;
  type: "public-key";
  response: {
    clientDataJSON: string;
    attestationObject: string;
    authenticatorData?: string;
    transports?: string[];
    publicKeyAlgorithm?: number;
    publicKey?: string;
  };
  authenticatorAttachment?: "platform" | "cross-platform";
  clientExtensionResults: Record<string, unknown>;
};

